/**
 * A task node. Leaves are checked off directly; parents derive progress from their leaves.
 */
export type Task = {
  id: string;
  title: string;
  description?: string;
  done: boolean;
  subtasks: Task[];
};

/**
 * A project — the root of a task tree (e.g. "FPS").
 */
export type Project = {
  id: string;
  name: string;
  description?: string;
  color?: string;
  tasks: Task[];
};

/** Progress summary for a task or project. */
export type Progress = { done: number; total: number; percent: number };

/** Creates a unique id for new tasks. */
export const newId = () =>
  `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;

/**
 * Counts completed vs total leaf tasks. Every leaf weighs the same,
 * so a parent's % reflects how much actual work is done beneath it.
 * @param tasks - task list to measure
 * @returns done/total leaves and a rounded percent
 */
export function measure(tasks: Task[]): Progress {
  let done = 0;
  let total = 0;
  const walk = (list: Task[]) => {
    list.forEach((t) => {
      if (t.subtasks?.length) walk(t.subtasks);
      else {
        total += 1;
        if (t.done) done += 1;
      }
    });
  };
  walk(tasks);
  return { done, total, percent: total ? Math.round((done / total) * 100) : 0 };
}

/**
 * Progress of a single task — a leaf is 0% or 100%, a parent reflects its leaves.
 * @param task - the task
 */
export function taskProgress(task: Task): Progress {
  if (!task.subtasks?.length) {
    return { done: task.done ? 1 : 0, total: 1, percent: task.done ? 100 : 0 };
  }
  return measure(task.subtasks);
}

const setAll = (task: Task, done: boolean): Task => ({
  ...task,
  done,
  subtasks: (task.subtasks || []).map((s) => setAll(s, done)),
});

/** Re-derives `done` on parents so it matches their children. */
const normalize = (tasks: Task[]): Task[] =>
  tasks.map((t) => {
    if (!t.subtasks?.length) return t;
    const subtasks = normalize(t.subtasks);
    return { ...t, subtasks, done: subtasks.every((s) => s.done) };
  });

/**
 * Applies a function to the task with the given id, anywhere in the tree.
 * @param tasks - tree to search
 * @param id - task id
 * @param fn - returns the replacement task, or null to delete it
 */
export function mapTask(tasks: Task[], id: string, fn: (t: Task) => Task | null): Task[] {
  const out: Task[] = [];
  tasks.forEach((t) => {
    if (t.id === id) {
      const next = fn(t);
      if (next) out.push(next);
    } else {
      out.push({ ...t, subtasks: mapTask(t.subtasks || [], id, fn) });
    }
  });
  return normalize(out);
}

/**
 * Toggles a task. Toggling a parent checks/unchecks all of its sub-tasks.
 * @param tasks - tree
 * @param id - task id to toggle
 */
export function toggleTask(tasks: Task[], id: string): Task[] {
  return mapTask(tasks, id, (t) => setAll(t, !t.done));
}

/**
 * Adds a new task under a parent (or at the root when parentId is null).
 * @param tasks - tree
 * @param parentId - parent id or null for top level
 * @param input - title and optional description
 */
export function addTask(
  tasks: Task[],
  parentId: string | null,
  input: { title: string; description?: string }
): Task[] {
  const task: Task = { id: newId(), title: input.title, description: input.description || '', done: false, subtasks: [] };
  if (!parentId) return [...tasks, task];
  return mapTask(tasks, parentId, (p) => ({ ...p, done: false, subtasks: [...(p.subtasks || []), task] }));
}

/** Removes a task (and its sub-tasks) from the tree. */
export function removeTask(tasks: Task[], id: string): Task[] {
  return mapTask(tasks, id, () => null);
}

/** Updates a task's title/description. */
export function editTask(tasks: Task[], id: string, patch: { title?: string; description?: string }): Task[] {
  return mapTask(tasks, id, (t) => ({ ...t, ...patch }));
}
